<script setup lang="ts">
useSeoPage('Choose a new password', 'Set a new password for your 247URL account.', '/reset-password')
const route=useRoute(); const form=reactive({email:String(route.query.email||''),token:String(route.query.token||''),password:'',password_confirmation:''}); const error=ref(''); const loading=ref(false); const complete=ref(false)
async function submit(){loading.value=true;error.value='';try{await $fetch('/api/backend/auth/reset-password',{method:'POST',body:form});complete.value=true}catch(e:any){error.value=e?.data?.errors?.password?.[0]||e?.data?.errors?.email?.[0]||e?.data?.message||'Unable to reset password.'}finally{loading.value=false}}
</script>
<template><AuthShell title="Choose a new password" description="Use a strong, unique password for this account."><div v-if="complete" class="rounded-lg border border-success-border bg-success-bg p-5"><p class="font-medium text-success">Password reset</p><p class="mt-2 text-sm text-text-secondary">Your password was updated and existing API sessions were revoked.</p><NuxtLink to="/login" class="btn-primary mt-5">Sign in</NuxtLink></div><form v-else class="grid gap-4" @submit.prevent="submit"><div><label class="label" for="email">Email</label><input id="email" v-model="form.email" class="input" type="email" required></div><div><label class="label" for="password">New password</label><input id="password" v-model="form.password" class="input" type="password" autocomplete="new-password" required></div><div><label class="label" for="confirm">Confirm password</label><input id="confirm" v-model="form.password_confirmation" class="input" type="password" autocomplete="new-password" required></div><p v-if="!form.token" class="rounded-md border border-warning-border bg-warning-bg p-3 text-xs text-warning">This reset link is missing its token. Request a new password reset email.</p><p v-if="error" class="field-error" role="alert">{{ error }}</p><button class="btn-primary w-full" :disabled="loading||!form.token">{{ loading?'Saving…':'Reset password' }}</button></form></AuthShell></template>
